mapper.insert:
INSERT INTO content_version (
    content_project_id, version_number, operation, status, title,
    content_format, request_key, task_id, source_run_id, artifact_id,
    artifact_version_id, error_code, error_summary, created_at, updated_at
) VALUES (
    #{contentProjectId}, #{versionNumber}, #{operation}, #{status}, #{title},
    #{contentFormat}, #{requestKey}, #{taskId}, #{sourceRunId}, #{artifactId},
    #{artifactVersionId}, #{errorCode}, #{errorSummary}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE content_version
SET status = 'RUNNING',
    updated_at = #{updatedAt}
WHERE task_id = #{taskId}
  AND source_run_id = #{runId}
  AND status = 'QUEUED'

UPDATE content_version
SET status = 'SUCCEEDED',
    artifact_id = #{artifactId},
    artifact_version_id = #{artifactVersionId},
    error_code = NULL,
    error_summary = NULL,
    updated_at = #{updatedAt}
WHERE task_id = #{taskId}
  AND source_run_id = #{runId}
  AND status IN ('QUEUED', 'RUNNING')
